PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE census_slices (
  phase       TEXT    NOT NULL CHECK (phase IN ('beta', 'live')),  -- beta＝開服前，live＝開服後
  realm       TEXT    NOT NULL,
  faction     TEXT    NOT NULL CHECK (faction IN ('Alliance', 'Horde')),
  snapshot    INTEGER NOT NULL,   -- 存檔裡最後一次看到任何人的時間（unix 秒）
  data        TEXT    NOT NULL,   -- 彙總 JSON（見 public/assets/denizens.js 的 buildSlices）
  upload_id   INTEGER NOT NULL,
  updated_at  INTEGER NOT NULL,
  PRIMARY KEY (phase, realm, faction)
);
